style.css:
@-moz-document domain("kirka.io") {
/* Estilo general del cuerpo */
    body {
        background-color: #121212;
        color: #ffffff;
        font-family: 'Roboto', sans-serif;
        margin: 0;
        padding: 0;
    }

    /* Encabezados personalizados */
    h1, h2, h3, h4, h5, h6 {
        color: #1db954;
        text-transform: uppercase;
        margin-bottom: 20px;
    }

    /* Párrafos estilizados */
    p {
        line-height: 1.6;
        margin-bottom: 20px;
    }

    /* Botones personalizados */
    button {
        background-color: #1db954;
        color: #121212;
        border: none;
        padding: 10px 20px;
        border-radius: 25px;
        font-size: 16px;
        cursor: pointer;
        transition: background-color 0.3s ease, transform 0.3s ease;
        margin: 10px;
    }

    button:hover {
        background-color: #14833b;
        transform: scale(1.1);
    }

    /* Enlaces estilizados */
    a {
        color: #1db954;
        text-decoration: none;
        transition: color 0.3s ease;
    }

    a:hover {
        color: #14833b;
    }

    /* Cuadros de texto personalizados */
    input[type="text"], input[type="password"], textarea {
        background-color: #333;
        color: #ffffff;
        border: 2px solid #1db954;
        padding: 10px;
        border-radius: 5px;
        outline: none;
        margin: 10px 0;
    }

    input[type="text"]:focus, input[type="password"]:focus, textarea:focus {
        border-color: #14833b;
    }

    /* Contenedor con sombra y esquinas redondeadas */
    .container {
        background-color: #1e1e1e;
        padding: 20px;
        border-radius: 10px;
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5);
        margin: 20px 0;
    }

    /* Estilos adicionales */
    .navbar {
        background-color: #333;
        padding: 10px;
        border-bottom: 2px solid #1db954;
    }

    .footer {
        background-color: #333;
        padding: 20px;
        text-align: center;
        border-top: 2px solid #1db954;
        margin-top: 20px;
    }

    .card {
        background-color: #1e1e1e;
        border-radius: 10px;
        padding: 20px;
        box-shadow: 0 4px 8px rgba(0, 0, 0, 0.5);
        margin: 20px 0;
        transition: transform 0.3s ease;
    }

    .card:hover {
        transform: scale(1.05);
    }
}
